begin; select set_config('request.jwt.claim.sub','7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d',true); select set_config('request.jwt.claims','{"sub":"7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d","role":"authenticated"}',true); do $$ begin if not exists(select 1 from schoolpro_schools where id='d342eb87-8d6a-477a-a380-7fab83f586b7' and owner_id='7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d' and name='IHLINK ACADEMY (Testing)')then raise exception 'Testing Academy only';end if;end $$;

insert into schoolpro_assignments(id,school_id,class_id,subject_id,title,instructions,due_at,created_by,max_score,session)
select md5('ihlink-academy-test-v1:term-assignment:'||a.class_id||':'||sub.id||':'||term)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',a.class_id,sub.id,'TEST: '||sub.name||' practice — '||term||' — '||sub.class_name,'Write three points about the topic discussed in class, complete the worked exercise and explain your approach. Fictional classroom practice for testing.',case term when 'First Term' then timestamptz '2025-11-14 15:00+00' when 'Second Term' then timestamptz '2026-03-06 15:00+00' else timestamptz '2026-06-12 15:00+00' end,m.user_id,10,'2025/2026' from schoolpro_subject_assignments a join schoolpro_subjects sub on sub.id=a.subject_id join schoolpro_members m on m.id=a.teacher_member_id cross join unnest(array['First Term','Second Term','Third Term'])term where a.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and a.session='2025/2026' and sub.code like 'TST-%' on conflict(id)do nothing;
insert into schoolpro_assignment_submissions(id,assignment_id,student_id,submission_text,score,feedback,status,graded_by,graded_at,submitted_at)
select md5('ihlink-academy-test-v1:term-submission:'||a.id||':'||s.id)::uuid,a.id,s.id,case when right(s.admission_number,3)::int%3=0 then 'TEST answer: I reviewed the example, explained each step and checked the final response.' when right(s.admission_number,3)::int%3=1 then 'TEST answer: I identified the main ideas and completed the practice. I would like help with the final question.' else 'TEST answer: My three key points and a worked solution are ready for teacher review.' end,case when right(s.admission_number,3)::int<=15 then 4+right(s.admission_number,3)::int%7 else null end,case when right(s.admission_number,3)::int<=15 then 'TEST: good effort; review the highlighted steps.' else null end,case when right(s.admission_number,3)::int<=15 then 'graded' else 'submitted' end,case when right(s.admission_number,3)::int<=15 then a.created_by else null end,case when right(s.admission_number,3)::int<=15 then a.due_at else null end,a.due_at-interval '1 day' from schoolpro_assignments a join schoolpro_students s on s.class_id=a.class_id and s.school_id=a.school_id where a.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and a.id in(select md5('ihlink-academy-test-v1:term-assignment:'||sa.class_id||':'||sa.subject_id||':'||term)::uuid from schoolpro_subject_assignments sa cross join unnest(array['First Term','Second Term','Third Term'])term where sa.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and sa.session='2025/2026') and s.admission_number like 'IH-TST-2026-%' and right(s.admission_number,3)::int<=30 on conflict(id)do nothing;

commit;